import json
import sys

def main():
    payload = json.load(sys.stdin)
    assert set(payload) == {'schema_version', 'refunds'}
    assert payload['schema_version'] == 2
    for row in payload['refunds']:
        assert set(row) == {'id', 'reason'}
    print(','.join(row['id'] for row in payload['refunds']))

if __name__ == '__main__':
    main()
